const fs = require('node:fs');
function createStore(filePath) {
  const store = {};
  const read = (filePath) => {
    const contents = fs.readFileSync(filePath, 'utf8');
    return JSON.parse(contents);
  };
  const write = (filePath, store) => {
    const contents = JSON.stringify(store, null, 2);
    fs.writeFileSync(filePath, contents);
  };
  const list = () => {
    return read(filePath).expenses;
  };
  const create = (body) => {
    const { description, amount_cents, category } = body;
    if (description && amount_cents && category) {
      const expense = { description, amount_cents, category };
      store.expenses.push(expense);
      write(filePath, store);
      return { deleted: false };
    } else {
      throw new Error('Invalid description or amount_cents');
    }
  };
  const deleteId = (id) => {
    const { expenses } = store;
    const index = expenses.findIndex((e) => e.id === id);
    if (index !== -1) {
      const deleted = expenses.splice(index, 1);
      write(filePath, store);
      return { deleted };
    } else {
      throw new Error('Expense not found');
    }
  };
