    const { expenses } = store;
    const by_category = expenses.reduce((acc, e) => {
      const { category } = e;
      acc[category] = acc[category] + e.amount_cents;
      return acc;
    }, {});
    return { count: expenses.length, total_cents: expenses.reduce((acc, e) => acc + e.amount_cents, 0), by_category };
